import{_ as a,a as i,b as o,c as t,d as n,e as r,f as s}from"./chunks/WF_BGs-02.C2X8bk-5.js";import{_ as l,a as d}from"./chunks/WF-BGFX.CFYu6eHs.js";import{_ as g,a as m,o as h,U as c}from"./chunks/framework.BS4h1hlk.js";const q=JSON.parse('{"title":"WordFlow","description":"","frontmatter":{"title":"WordFlow","meta":[{"name":"description","content":"WordFlow, a peaceful word-finding mobile game"},{"name":"keywords","content":"Wordflow, 2D, UI"}],"thumb":"/img/WF-featured.png","hidden":false,"featured":true},"headers":[],"relativePath":"portfolio/WordFlow/index.md","filePath":"portfolio/WordFlow/index.md","lastUpdated":1791046427000}'),p={name:"portfolio/WordFlow/index.md"};function u(f,e,y,w,v,_){return h(),m("div",null,e[0]||(e[0]=[c('<h1 id="wordflow" tabindex="-1">WordFlow <a class="header-anchor" href="#wordflow" aria-label="Permalink to &quot;WordFlow&quot;">​</a></h1><h3 id="software-figma-photoshop-unity" tabindex="-1">Software: Figma, Photoshop, Unity <a class="header-anchor" href="#software-figma-photoshop-unity" aria-label="Permalink to &quot;Software: Figma, Photoshop, Unity&quot;">​</a></h3><img loading="lazy" src="'+a+'"><img loading="lazy" src="'+i+'"><p>WordFlow is a relaxing word search puzzle game where players solve engaging levels and journey through a variety of beautiful new locations.</p><h3 id="main-game-ui" tabindex="-1">Main Game UI <a class="header-anchor" href="#main-game-ui" aria-label="Permalink to &quot;Main Game UI&quot;">​</a></h3><img loading="lazy" src="'+o+'"><p>Each level featured a collection of fun, themed words to discover across the game board. Unlocking new, beautiful locations gave players a rewarding sense of achievement and progress.</p><img loading="lazy" src="'+t+'"> A daily challenge mode introduced players to uplifting quotes from a new author each day, while encouraging them to maintain a daily streak for ongoing inspiration. <h3 id="wireframes" tabindex="-1">Wireframes <a class="header-anchor" href="#wireframes" aria-label="Permalink to &quot;Wireframes&quot;">​</a></h3><img loading="lazy" src="'+n+'"> Following some initial rounds of UA testing and prospective surveys, I identified opportunities to create a more marketable theme and strengthen the overall player experience. I then took ownership of the wireframing and UX design, shaping a clear gameplay loop and user flow that encouraged players to progress level by level without feeling overwhelmed. <p>I recommended removing unnecessary friction by taking players directly into their current level, while redesigning the endgame and home experience around a minimal, lightweight interface that made the next action immediately clear.</p><p>To strengthen engagement and long-term retention, I designed several progression mechanics that layered motivation throughout the experience. A rolling, never-ending quest system gave players ongoing goals and encouragement during core gameplay, while “Daily Knowledge” created an additional reason to continue playing. I also designed the Daily Challenge streak and Quote &amp; Postcard collections to introduce longer-term progression, giving players tangible goals and a stronger sense of achievement beyond individual levels.</p><h3 id="animation-fx" tabindex="-1">Animation &amp; FX <a class="header-anchor" href="#animation-fx" aria-label="Permalink to &quot;Animation &amp; FX&quot;">​</a></h3><video loading="lazy" controls autoplay loop style="max-width:100%;" width="300"><source src="'+l+'" type="video/mp4"></video> Engaging core game FX gave players immediate feedback, while fun and imaginative hint animations strengthened the hint theming and individuality, rewarding players for using coins. <h3 id="background-images" tabindex="-1">Background Images <a class="header-anchor" href="#background-images" aria-label="Permalink to &quot;Background Images&quot;">​</a></h3><p><img loading="lazy" src="'+r+'"> <img loading="lazy" src="'+s+'"></p><p>Initial user testing and prospective player surveys showed that players responded most positively to a visual style that felt realistic, yet beautiful and charming, with a subtle painterly quality.</p><p>As the game required a large variety of travel destinations, I needed a way to generate new locations at scale without sacrificing visual consistency or limiting the player’s sense of progression through a lack of content. To address this, I trained an existing AI model using a LoRA (Low-Rank Adaptation), allowing me to generate a consistent visual style across a wide range of environments and locations.</p><p>Travel destinations were then organised into thematic groups, such as “Natural Wonders of North America,” with location selection informed by user research. Particular emphasis was placed on destinations that players identified as aspirational places they would genuinely like to visit, helping to make the player’s journey feel rewarding and motivating.</p><video loading="lazy" controls autoplay loop><source src="'+d+'" type="video/mp4"></video><p>Subtle animations using Unity particle effects and shaders brought the backgrounds to life, enhancing the atmosphere while maintaining performance and keeping asset sizes minimal.</p>',25)]))}const F=g(p,[["render",u]]);export{q as __pageData,F as default};
